from xml.etree import ElementTree as ET

def extract_phi(xml_string):
    # Define regular expressions for PHI patterns
    name_pattern = r'\b[A-Z][a-z]+ [A-Z][a-z]+\b'
    date_pattern = r'\d{4}-\d{2}-\d{2}'
    location_pattern = r'\b[A-Z][a-z]+, [A-Z]{2} \d{5}\b'
    phone_pattern = r'\b\d{3}[-\.\s]?\d{3}[-\.\s]?\d{4}\b'
    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    id_pattern = r'\b\d{3}-\d{2}-\d{4}\b'
    age_pattern = r'\b\d{1,3}\b'
    other_pattern = r'\b[A-Z]{2}\b'

    # Parse XML string into an ElementTree object
    root = ET.fromstring(xml_string)

    # Initialize list to store PHI spans
    phi_spans = []

    # Iterate over all text in the XML tree
    for elem in root.iter():
        if elem.text:
            # Find all matches for each pattern
            name_matches = re.findall(name_pattern, elem.text)
            date_matches = re.findall(date_pattern, elem.text)
            location_matches = re.findall(location_pattern, elem.text)
            phone_matches = re.findall(phone_pattern, elem.text)
            email_matches = re.findall(email_pattern, elem.text)
            id_matches = re.findall(id_pattern, elem.text)
            age_matches = re.findall(age_pattern, elem.text)
            other_matches = re.findall(other_pattern, elem.text)

            # Add matches to the list of PHI spans
            for match in name_matches:
                phi_spans.append({
                    'start': elem.text.find(match),
                    'end': elem.text.find(match) + len(match),
                    'label': 'NAME',
                    'text': match
                })
            for match in date_matches:
                phi_spans.append({
                    'start': elem.text.find(match),
                    'end': elem.text.find(match) + len(match),
                    'label': 'DATE',
                    'text': match
                })
            for match in location_matches:
                phi_spans.append({
                    'start': elem.text.find(match),
                    'end': elem.text.find(match) + len(match),
                    'label': 'LOCATION',
                    'text': match
                })
            for match in phone_matches:
                phi_spans.append({
                    'start': elem.text.find(match),
                    'end': elem.text.find(match) + len(match),
                    'label': 'PHONE',
                    'text': match
                })
            for match in email_matches:
                phi_spans.append({
                    'start': elem.text.find(match),
                    'end': elem.text.find(match) + len(match),
                    'label': 'EMAIL',
                    'text': match
                })
            for match in id_matches:
                phi_spans.append({
                    'start': elem.text.find(match),
                    'end': elem.text.find(match) + len(match),
                    'label': 'ID',
                    'text': match
                })
            for match in age_matches:
                phi_spans.append({
                    'start': elem.text.find(match),
                    'end': elem.text.find(match) + len(match),
                    'label': 'AGE',
                    'text': match
                })
            for match in other_matches:
                phi_spans.append({
                    'start': elem.text.find(match),
                    'end': elem.text.find(match) + len(match),
                    'label': 'OTHER',
                    'text': match
                })

    # Filter out duplicate spans
    phi_spans = [{**dict(t) for t in {tuple(d.items()) for d in phi_spans}}

    # Return the list of PHI spans as a JSON object
    return json.dumps({'spans': phi_spans})

