Note: The "PHONE" label is used for the amount as it is a numeric value that could potentially be a phone number. However, in this context, it is more likely to be an amount. If you want to use a more specific label, you can replace "PHONE" with "AMOUNT".

```python
import re
import json

def deidentify_phi(text):
    # Regular expressions for PHI patterns
    name_pattern = r"Name: ([A-Za-z\s]+)"
    date_pattern = r"(?:StatementBeginDate|StatementEndDate|Date): (\d{8})"
    location_pattern = r"Address: ([A-Za-z\s]+, [A-Za-z\s]+, US)"
    phone_pattern = r"ContactPhone: \d{3}-\d{3}-\d{4}-\d{4}"
    email_pattern = r"ContactURL: https?://[^ ]+"
    id_pattern = r"(?:BankID|TRN|AccountNumber): (\d+)"
    age_pattern = None  # Not applicable in this text
    other_pattern = r"(?:ContactName|Description|Currency|StatementFrequency|AccountType|AvailableBalance|LedgerBalance|HighestBalance|LowestBalance|HighestCredit|LowestDebit|AverageDailyBalance|StatementGenerationDate|PostDate|DebitCreditFlag|Amount): [^:]+"

    # Find all matches for each pattern
    names = re.findall(name_pattern, text)
    dates = re.findall(date_pattern, text)
    locations = re.findall(location_pattern, text)
    phones = re.findall(phone_pattern, text)
    emails = re.findall(email_pattern, text)
    ids = re.findall(id_pattern, text)
    others = re.findall(other_pattern, text)

    # Create a list of spans
    spans = []
    for name in names:
        spans.append({
            "start": text.find("Name: " + name),
            "end": text.find("Name: " + name) + len(name) + 6,
            "label": "NAME",
            "text": name
        })
    for date in dates:
        spans.append({
            "start": text.find("StatementBeginDate: " + date) if "StatementBeginDate" in text else text.find("StatementEndDate: " + date),
            "end": text.find("StatementBeginDate: " + date) + len(date) + 15 if "StatementBeginDate" in text else text.find("StatementEndDate: " + date) + len(date) + 15,
            "label": "DATE",
            "text": date
        })
    for location in locations:
        spans.append({
            "start": text.find("Address: " + location),
            "end": text.find("Address: " + location) + len(location) + 8,
            "label": "LOCATION",
            "text": location
        })
    for phone in phones:
        spans.append({
            "start": text.find("ContactPhone: " + phone),
            "end": text.find("ContactPhone: " + phone) + len(phone) + 13,
            "label": "PHONE",
            "text": phone
        })
    for email in emails:
        spans.append({
            "start": text.find("ContactURL: " + email),
            "end": text.find("ContactURL: " + email) + len(email) + 13,
            "label": "EMAIL",
            "text": email
        })
    for id in ids:
        spans.append({
            "start": text.find("BankID: " + id) if "BankID" in text else text.find("TRN: " + id) if "TRN" in text else text.find("AccountNumber: " + id),
            "end": text.find("BankID: " + id) + len(id) + 7 if "BankID" in text else text.find("TRN: " + id) + len(id) + 4 if "TRN" in text else text.find("AccountNumber: " + id) + len(id) + 14,
            "label": "ID",
            "text": id
        })
    for other in others:
        spans.append({
            "start": text.find(other + ": ") + len(other) + 2,
            "end": text.find(other + ": ") + len(other) + 2 + len(re.search(other + ": [^:]+", text).group().split(": ")[1]),
            "label": "OTHER",
            "text": re.search(other + ": [^:]+", text).group().split(": ")[1]
        })

    # Return the spans as a JSON object
    return json.dumps({"spans": spans})

print(deidentify_phi(text))
